 "content": "def transform(grid):
    """Reflect a 3x3 grid into a 3x3 mirrored tiling centered on the input."""
    if len(grid) != 3 or any(len(row) != 3 for row in grid):
        raise ValueError("expected a 3x3 input")
    out = []
    for block_row in range(3):
        rows = [[] for _ in range(3)]
        for block_col in range(3):
            block = [row[:] for row in grid]
            if block_row == 0:
                block = block[::-1]
            if block_col == 0:
                block = [row[::-1] for row in block]
            for i in range(3):
                rows[i].extend(block[i])
        out.extend(rows)
    return out

if __name__ == '__main__':
